#include <SoftwareSerial.h>
#include <TinyGPS++.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// GPS Tracker Logger
// Parses NEO-6M NMEA sentences and displays position + speed on an OLED.

SoftwareSerial gpsSerial(4, 3); // RX, TX
TinyGPSPlus gps;
Adafruit_SSD1306 display(128, 64, &Wire, -1);

void setup() {
  gpsSerial.begin(9600); // NEO-6M's default baud rate
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.setTextColor(SSD1306_WHITE);
}

void loop() {
  // Feed every incoming byte to the parser — a full sentence can arrive
  // across many loop() iterations, a character or two at a time.
  while (gpsSerial.available() > 0) {
    gps.encode(gpsSerial.read());
  }

  if (gps.location.isUpdated()) {
    updateDisplay();
  }
}

void updateDisplay() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);

  display.print("Lat: ");
  display.println(gps.location.lat(), 6);

  display.print("Lng: ");
  display.println(gps.location.lng(), 6);

  display.print("Speed: ");
  display.print(gps.speed.kmph(), 1);
  display.println(" km/h");

  display.print("Satellites: ");
  display.println(gps.satellites.value());

  display.display();
}
